  "DROIDLOOM_NATIVE_GENERATION=1;ROLE=ART_BRIDGE;ABI=1;PROTOCOL=DLOOMGE1-PROCMET2;";
#else
  "DROIDLOOM_NATIVE_GENERATION=0;ROLE=ART_BRIDGE;ABI=1;PROTOCOL=DLOOMGE1-PROCMET2;";
#endif

